contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        address beforeCeo = c.ceoAddress(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.DrugDealer(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted ? c.ceoAddress() == beforeCeo : c.ceoAddress() == address(this));
    }

    receive() external payable {}
}

