pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 x) internal {
        address beforeCeo;
        try c.ceoAddress() returns (address __r) { beforeCeo = __r; } catch { return; }
        bool reverted;
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ? c.ceoAddress() == beforeCeo : c.ceoAddress() == address(this));
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
